pub const OWNERSHIP_MARKER: &str =
    "<!-- Managed by rudis-lite. Do not edit this file manually. -->";
pub const UPSTREAM_REVISION: &str = "e216888ea226cdb99e27be11c1f963e12eb79c4d";

pub struct Template {
    pub name: &'static str,
    pub source: &'static str,
    pub content: &'static str,
}

macro_rules! template {
    ($name:literal) => {
        Template {
            name: $name,
            source: concat!("templates/commands/", $name, ".md"),
            content: include_str!(concat!("../templates/commands/", $name, ".md")),
        }
    };
}

static TEMPLATES: [Template; 23] = [
    template!("analyze"),
    template!("brd"),
    template!("checklist"),
    template!("clarify"),
    template!("constitution"),
    template!("converge"),
    template!("deploy"),
    template!("fan"),
    template!("implement"),
    template!("operate"),
    template!("plan"),
    template!("postmortem"),
    template!("prototype"),
    template!("redesign"),
    template!("revamp"),
    template!("rudis"),
    template!("specify"),
    template!("taskstoissues"),
    template!("tasks"),
    template!("test"),
    template!("tracer"),
    template!("ultimate"),
    template!("upgrade"),
];

pub fn all() -> &'static [Template] {
    &TEMPLATES
}

pub fn find(name: &str) -> Option<&'static Template> {
    TEMPLATES.iter().find(|template| template.name == name)
}

pub fn managed_content(template: &Template) -> String {
    let body = template.content;
    if let Some(frontmatter_end) = body
        .strip_prefix("---\n")
        .and_then(|rest| rest.find("\n---"))
    {
        let frontmatter_start = "---\n".len();
        let split_at = frontmatter_start + frontmatter_end + "\n---".len();
        return format!(
            "{}\n{}\n<!-- Upstream: {} @ {} -->\n\n{}",
            &body[..split_at],
            OWNERSHIP_MARKER,
            template.source,
            UPSTREAM_REVISION,
            body[split_at..].trim_start_matches('\n'),
        );
    }
    format!(
        "{OWNERSHIP_MARKER}\n<!-- Upstream: {} @ {} -->\n\n{}",
        template.source, UPSTREAM_REVISION, body
    )
}
